/*
  Helper for passing in props to React components being tested.

  Define some default props up above,
  ex
  let fillInProps;
  beforeEach(() => {
    // only relevant key/values filled in
    fillInProps = createFillinProps({
      locations: fromJS([
        { id: 'AAA', name: 'Alphabet Alimonies' },
        { id: 'DDD', name: 'Delta Data Dongles' },
        { id: 'GGG', name: 'Gorilla Garnishes' },
      ]),
      inactives: fromJS([
        { locationId: 'AAA', id: '001', active: 0 },
        { locationId: 'DDD', id: '002', active: 1 },
        { locationId: 'GGG' },
      ]),
      allLocationsViewScenario: false,
      contentGroupName: 'Burker King',
      inactiveForNewLocations: 0,
      updateStateByKey: () => () => {},
    });
  });

  then later, so the prop validation wont complain, you'll have everything you need
  by default, and anything you want to override you pass in
  mount(<Locations {...fillInProps({ allLocationsViewScenario: true })} />)
  .find('.specific-locations-config-component')
  .should.not.exist;
*/
const createFillinProps = (defaultPropsToFill) => (overrideWithTheseProps = {}) => (
    { ...defaultPropsToFill, ...overrideWithTheseProps }
);

export default createFillinProps;